import{c as s,Q as a,j as t,m as r}from"./chunks/framework.BXc4yaFE.js";const l=JSON.parse('{"title":"Stop Comparing LLM Agents Without Disclosing the Harness","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.23950","title":"Stop Comparing LLM Agents Without Disclosing the Harness","arxiv_id":2605.2395,"collected_at":"2026-08-01T00:00:00.000Z","collected_by":"routine-d","domain":"Harness Engineering","pdf_path":"pdfs/2605.23950.pdf","year":2026},"headers":[],"relativePath":"research/papers/2026-08-01-stop-comparing-agents-without-disclosing-harness-2605-23950.md","filePath":"research/papers/2026-08-01-stop-comparing-agents-without-disclosing-harness-2605-23950.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-08-01-stop-comparing-agents-without-disclosing-harness-2605-23950.md"};function o(i,e,h,c,p,d){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="stop-comparing-llm-agents-without-disclosing-the-harness" tabindex="-1">Stop Comparing LLM Agents Without Disclosing the Harness <a class="header-anchor" href="#stop-comparing-llm-agents-without-disclosing-the-harness" aria-label="Permalink to &quot;Stop Comparing LLM Agents Without Disclosing the Harness&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文主張長任務上對 LLM agent 的效能比較普遍忽略了一個關鍵變因：模型周遭的執行基礎設施（agent harness）——管理 context、工具呼叫、協調與驗證的系統層。研究者常把效能提升歸因於模型選擇，實際上很大一部分增益來自 harness 配置的差異。</p><p>作者提出「Binding Constraint Thesis」：在此制度下，效能變異更大程度由 harness 配置決定，而非模型選擇。論證分三路徑：① <strong>控制理論框架</strong>——把 harness 建模為調節閉環系統的控制器，LLM 作為底層 policy，解釋為何微小的基礎設施調整可能蓋過模型替換的影響；② <strong>實證證據</strong>——檢視已發表 benchmark、真實世界實作與受控變異分解實驗；③ <strong>評測協定提案</strong>——要求明確揭露 harness 配置的 harness-aware 評測標準。</p><p>關鍵發現：harness 造成的效能變異經常超過模型造成的變異，甚至存在僅因 harness 配置不同就導致模型排名反轉的案例。當前 leaderboard 比較普遍缺乏對基礎設施選擇的透明度，可能誤導了對「真實科學進展」的認知。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>直接支持 core.md「Agent = Model + Body + Harness」公理與 <code>core.md §PROPOSE 委派</code>（原 <code>refs/graph-engineering.md</code>） G2「gate 不配模型」的判斷——本文提供實證與形式化論證：模型換檔位（cost/quality/ceiling/frontier）前，若未同時控制 harness 配置，觀測到的效能差異可能是 harness artifact 而非模型能力差異，呼應本 workspace <code>refs/model-profiles.md</code> 換模型重審時應先排查 harness 變因。</p>',7)])])}const m=s(n,[["render",o]]);export{l as __pageData,m as default};
